CARDS=[]
def add(id,module,pre,scope,method,pitfall,mastery,difficulty,variants):
 CARDS.append(dict(id=id,module=module,pre=pre,scope=scope,method=method,pitfall=pitfall,mastery=mastery,difficulty=difficulty,variants=variants))
add('OS01','系统与进程','CPU与I/O、并发和并行','多道多任务、系统利用率、启动初始化和微内核。','从资源使用时间线判断单CPU上的交替并发与CPU/I/O真正并行；多道提高重叠机会但受内存和调度开销限制。启动按固件→引导程序→内核装入初始化。','多任务必须多CPU；多道必有虚存；进程越多利用率越高；每次启动都重建磁盘文件系统。','能说明概念成立的最低条件和多道过量的反例；高分区分启动步骤和格式化步骤。','基础到常规；初始化与磁盘安装过程交叉需辨析。',[('并发与结构','并发|并行|多道|多任务|批处理|微内核','微内核强调可靠性、扩展性等，消息通信增加开销，不能推断性能必更高。'),('启动与初始化','引导|初始化|MBR','固件与磁盘引导链把OS装入RAM，再建立中断向量等内核运行结构；磁盘分区和文件系统通常早已存在。')])
add('OS02','系统与进程','特权级、中断异常','系统调用流程、用户／内核态、特权指令和软硬件分工。','应用传参并执行陷入指令，硬件保存必要断点状态并切态，内核执行服务，返回用户代码。普通库函数是否需内核取决于功能。','trap指令本身必须特权导致用户无法调用；所有库函数切内核；模式切换等于进程切换；发生异常前已内核态。','能画调用与返回步骤并分类每项操作；高分区分硬件保存与OS保存的现场。','常规；系统调用、缺页、外中断及进程调度混合选项为综合。',[('特权及调用路径','.*','用户态只执行非特权，内核态可执行两类；I/O、开关中断等特权，系统调用指令允许用户执行；指令约定服从题设。')])
add('OS03','系统与进程','进程与PCB、就绪队列','创建终止、三态转换、上下文和I/O完成流程。','运行→阻塞因为等待事件；运行→就绪因为抢占或主动让出；阻塞→就绪因为事件到达，真正运行还需调度。创建初始化PCB，终止回收资源。','I/O完成直接运行；时间片耗尽算唤醒；系统中断向量表基址随每个进程切换；终止父必杀全部子进程。','能按事件画状态与队列变化；高分分清CPU正在处理谁的中断与请求进程自身状态。','常规到综合；键盘完整时序和进程上下文边界是难点。',[('状态创建与终止','.*','PC、通用寄存器、栈和地址空间相关状态属上下文；全系统结构不因普通切换而一律更换。')])
add('OS04','系统与进程','进程地址空间、栈、调度','用户与内核线程、共享资源及独立执行现场。','同进程线程共享地址空间、堆、全局和打开文件；各有执行栈与寄存器现场。用户线程由库管理，内核是否能独立调度取决于映射模型。','逻辑私有栈误说成同地址空间内绝对不可访问；跨进程同名变量自动共享；用户线程都由OS逐一建TCB。','能把每项状态放到进程级或线程级；高分只对真实共享读写加互斥，不扩大临界区。','基础到综合；共享变量冲突与调度模型联动需精确。',[('共享与私有及线程实现','.*','同进程线程切换通常不换页表基址；独立内核线程有自己的内核栈，不能与进程共享堆混淆。')])
add('OS05','同步与调度','原子性、读写集合、交错执行','临界区、Peterson/TSL/Swap、管程、关中断及Bernstein条件。','先找共享对象及读写冲突，再检查进入区是否原子、退出是否释放。交错题按每线程内部顺序列所有可行组合；读读不冲突，写写与读写需要协调。','普通交换函数替代原子Swap；if检查锁只试一次；退出把lock置真；忙等满足让权等待；用户态关中断。','能给互斥成立证明或最短交错反例；高分同时检验进展、有限等待及单CPU关中断忙等死锁。','综合到较难；原子性和所有交错的证明比背定义更重要。',[
('互斥机制和反例','.*','Peterson需依其内存读写模型；TSL/Swap自旋忙等；记录型信号量阻塞可让权；管程条件wait进入条件队列。'),
('读写集合与交错','集合|交错|丢失更新|读改写|写者|冲突','Bernstein要求W(P)∩W(Q)、R(P)∩W(Q)、W(P)∩R(Q)为空；R(P)∩R(Q)可非空。')])
add('OS06','同步与调度','P/V原子操作、计数和前驱','容量限制、互斥、生产消费、前驱、分组消费及防死锁设计。','每种数量约束设计数信号量，每个先后事件设同步信号量，每个真实临界资源设互斥量。写出初值及P/V配对，获取可用资源的P放在不会阻塞其他释放者的位置。','持互斥锁等待空位／产品导致死锁；同线程先后重复设信号量；只被一个人使用的工具也加锁；负值当剩余资源。','能说明每个信号量的物理意义和不变量，验证无死锁、无超容量、保留允许并发。','综合到较难；多约束交叉和分组消费不能只套生产者消费者模板。',[
('计数含义与简单互斥同步','当前值|负值|初值|单次|两次修改|记录型|原子|阻塞让权','S≥0表示可用量，S<0时绝对值是等待者数；互斥常初值1，事件同步常初值0。'),
('有界容量与生产消费','生产|消费|座位|取号|容量|博物馆|信箱|植树|缓冲|连续取10','将空位、产品种类、工具分别建模；连续取10件需要组级互斥但逐件等待，避免一次锁住所有生产者。'),
('前驱图同步','前驱|跨线程|依赖','只为跨线程必要边设同步；生产完成V，依赖者开始前P；分叉分别通知，汇合全部等待。'),
('冲突对象与哲学家','共享变量|最大并发|哲学家|筷|碗','对资源获取顺序或并发人数施加防环条件；碗与筷数量约束同时核对，不一把全局锁抹掉可并发性。')])
add('OS07','同步与调度','到达完成时间、就绪与阻塞','FCFS/SJF/优先级/RR/反馈队列、饥饿、动态优先级与CPU-I/O重叠。','按所有到达、完成、时间片到期及允许抢占时刻建立事件表。周转=完成−到达，等待按就绪累计；高响应比=(等待+服务)/服务。','未到达任务参与选择；优先数大小方向看反；把每次时钟中断当调度；忽略重入重置时间片。','能画唯一可核算时间线并列每次选择理由；高分在离散抢占时点和切换开销下重新算。','常规到较难；2026动态优先级与离散时钟约束需独立事件模拟。',[
('调度性质与饥饿','高响应比|动态|饥饿|I/O密集|老化|多级|反馈|时间片大小|临界区|依赖PCB','老化改善长期等待；I/O密集及时运行可提高设备重叠；普通用户临界区不普遍禁止调度。'),
('时间线与调度次数','到达|周转|等待|次数|RR|时钟|SJF|FCFS|抢占|队尾|切换|调度时刻|时间片耗尽','分开调度器被调用与实际切换的题目口径；新到高优先级也必须等题许的抢占时点。'),
('多资源重叠','交叠|三资源|流水调度|最短总时长','CPU与输入输出各画资源行，满足进程内部先后和资源独占再尽量重叠。'),
('实现结构成本','有序链表','维护优先有序链表插入需O(n)，从表头取最高优先级为O(1)，不把两阶段合并计。')])
add('OS08','同步与调度','资源向量、等待图','死锁条件、预防避免检测解除、安全序列和资源数量界。','Need=Max−Allocation，Work=Available；反复找Need≤Work的未完成进程，模拟完成后Work加其Allocation。安全序列枚举需回溯恢复Work。','不安全等于已死锁；试分配只检查当前可用而不查安全；释放Max而非Allocation；总资源减法错。','能证明安全或指出无可完成进程；高分枚举全部安全序列并构造达到资源界的状态。','常规到较难；全部序列与异构需求最坏分配为难点。',[
('银行家与概念','安全|Need|可用|银行家|避免|预防|检测|解除|需求信息','避免需最大需求等先验；预防破坏必要条件；检测允许分配后再查。'),
('资源数量与等待环','同类|最少|最大需求|各需|等待环|哲学家','同类可共享多实例资源，保证无死锁常用sum(max_i−1)+1，须满足资源需求可实现等原题条件；异类用实际等待环而非套此式。')])
add('OS09','内存管理','逻辑地址、物理地址、区间','分区、段式、重定位、伙伴、程序区段和共享段。','动态分区先按算法选空闲块，释放时按地址合并邻居后重排。段式先检查段号／段内界限，再加段基址。变量区分指针自身位置与所指对象。','最佳适应按地址找；同大小相邻块就是伙伴；段越界当缺页；malloc返回物理地址；全局指针所指也必在数据段。','能维护空闲表并给地址保护判定；高分解释堆栈代码数据及内核PCB的分区。','常规；连续分配演化与变量地址空间联合为综合。',[
('分区与伙伴','分区|适应|碎片|伙伴','伙伴合并要求同阶且互为按对齐关系定义的伙伴，不是任意相邻同大小。'),
('分段保护共享重定位','段|上下界|基址|重定位|逻辑地址|装载|装入','段内偏移必须小于段长；共享段可在不同进程有不同段号，同指物理内容。'),
('程序内存布局','PCB|malloc|main|指针|length|堆|栈','代码只读区、全局静态数据区、动态堆、局部栈和内核区分开；权限也分区。')])
add('OS10','内存管理','位分解、页表项、主存访问','单／多级分页、TLB、缺页、共享、页表自映射和跨Cache综合。','地址先拆VPN和页内偏移；TLB命中取PFN，未命中逐级查表；P=0触发缺页，装页更新映射后重执行。物理地址=PFN×页大小+原偏移。','TLB未中即缺页；页表基址当虚地址；非连续物理页框仍把整数组当物理连续；保留位参与多级索引。','能逐步算每级表项地址、有效位和最终物理地址；高分解释页表自映射及与Cache并行索引条件。','综合到较难；多级表、缺页重执行和页表自身地址是核心难题。',[
('字段与表项地址','页号|页框|地址|字段|索引|页大小|虚实|PDBR|页目录|表项|页表基址|代码同页','表项地址=该级表物理基址+索引×表项大小，逐级读下一基址；末级偏移不变。'),
('TLB组相联与一致性','TLB|虚页标记','TLB按虚页号分组标记，Cache通常按物理块；一致状态有效TLB项不可对应不驻留页。'),
('缺页与时间','缺页|页故障|存在位|常驻|访存时间|重执行|首次|页缓冲','区分空闲页框装入和替换；计时按题是否串行查TLB／页表、重启是否再次查TLB，不能死套一个公式。'),
('多级表空间及页表自映射','多级|二级|三级|目录|自映射|整张页表|页表所在页','多级表主要节省稀疏空间和连续分配要求；表项总数与实际分配表页分开，保留位不参与索引。'),
('共享与上下文','共享|切换|映射文件|权限','共享页虚页号与权限可不同但物理页相同；同进程线程通常共享页表，进程切换恢复相应基址。'),
('位图及层次辨析','位图|MMU|交换粒度|直写|Cache缺失','页框位图只按页框总数计算；MMU地址／权限检查、CPU异常与OS处理分工要分开。')])
add('OS11','内存管理','页框、访问序列、时间顺序','FIFO/LRU/CLOCK/改进CLOCK和自定义页回收模拟。','每次访问先判驻留；缺页有空框先装，无空框按算法选。分别维护装入时刻、最近访问和访问／修改位，不能用一张混合顺序表。','缺页数等于置换数；初始驻留页算首次缺页；CLOCK起始指针错；清访问位后未更新扫描状态。','能完整列每次页框、位和时钟指针并核算；高分解释FIFO Belady异常与LRU栈性质。','常规到综合；定时回收和保留内容的空闲链为较难。',[
('经典置换','FIFO|LRU|CLOCK|Belady|待淘汰|置换|页框','FIFO看装入先后，LRU看最近使用，改进CLOCK兼顾访问和修改；每次扫描是否清位依题规则。'),
('定时回收与复用','定时|空闲链|保留内容|驻留集|时间轴','回收页框不一定立即抹去内容，可能从保留页找回；按扫描时刻和链头规则更新，不套普通LRU。')])
add('OS12','内存管理','局部性、驻留集、工作集','虚存容量、页框分配、工作集、抖动、页缓冲及最少页框。','工作集取给定窗口最近引用页的集合并去重；分配政策与局部／全局置换分开。抖动是频繁缺页压低有效计算，常需降低多道度或增加合适页框。','工作集等于最近引用次数；页缓冲必降低缺页次数；虚拟地址空间只由物理内存决定；多级页表直接加速。','能按窗口算集合并解释性能变化原因；高分由一条指令的寻址过程推最少同时驻留页。','常规到综合；最少页框与回收缓冲需看指令和状态。',[
('容量与分配政策','容量|固定|可变|局部|全局|虚拟地址|最少页框|单条指令','虚地址空间由有效地址位数界定，实现可用容量另受后备等限制；不能一律内外存简单相加。'),
('局部性工作集及抖动','.*','页缓冲保留被淘汰内容主要减少磁盘I/O；缺页发生与实际读盘不是同一计数。')])
add('OS13','文件与I/O','目录、inode、文件描述符','目录路径、创建打开读写关闭删除、VFS、权限和文件总数。','路径逐级目录查名字得inode；open建立进程／系统打开表，read/write经fd和文件位置访问，close减打开引用。删除目录名与释放底层内容要考虑链接和打开状态。','open读入全部文件；close减硬链接计数；文件名存inode里；inode数量决定单文件最大长度。','能逐步列所访问元数据和数据块，扣除已缓存部分；高分区分三种引用及目录树删除。','常规到综合；元数据缓存、链接和索引联合访问为较难。',[
('操作路径与打开表','目录|open|read|打开|关闭|FCB|描述符|路径|文件名|inode|删除|创建','独立open可有独立文件偏移；共享同一打开表项的情形依题关系；删除非空目录树需按题要求先处理子项，不把rmdir说成自动递归。'),
('容量权限与格式化','数量|权限|属性|格式化|根目录|位向量','文件总数受inode数量和剩余数据块双重约束；权限按用户类别×独立权限位数计算。'),
('VFS','VFS','VFS统一不同本地和网络文件系统接口，不是另一种虚拟存储，也不保证访问加速。')])
add('OS14','文件与I/O','块／簇、指针大小、间接层级','连续、链接、FAT、索引、区段以及随机访问次数和最大文件。','每索引块容纳K=B/地址项字节数。直接d项加各级间接时最大数据块数=d+K+K²+K³（仅加实际提供级）。偏移先除块长定位逻辑块，再确定索引层级。','索引块算作文件内容容量；inode总数作单文件长度；缓存FAT仍逐簇读磁盘表；按扇区而非簇取整。','能区分数据块、索引块、元数据块访盘次数；高分优化区段字段位宽并分析中间插入。','综合到较难；混合索引、缓存及文件插入重排必须逐层计算。',[
('分配方式与扩展','连续|链接|随机|分配|预读|取整|按簇|可变长','连续随机访问方便但扩展受限；链接适合顺序，索引支持随机；每块带指针时有效载荷扣指针。'),
('直接多级间接索引','索引|间接|偏移|文件长度|末簇|文件数|inode','已缓存inode不再访盘读inode，但所需间接索引块仍要计；边界用0基逻辑块号。'),
('FAT与路径','FAT|后继|目录项|路径','当前簇号索引FAT，表项保存后继簇号；FAT在内存则沿链查询不产生读FAT盘开销。'),
('区段和中间插入','区段|插入|字段宽度','连续文件插入可移动较短侧但需检查前后空间；区段描述起始块和长度分别按范围编码。')])
add('OS15','文件与I/O','位图、取整、逻辑格式化','空闲空间管理、位图定位、格式化顺序和删除元数据更新。','N块位图需ceil(N/8)B，再按存放块大小向上取整。块号q对应字节floor(q/8)、位q mod8，位图自身在盘中的块号另算。','按空闲块数算位图长度；分配位0/1含义擅自固定；低级格式化、分区和文件系统初始化混同。','能从释放块号定位位图字节和位；高分同时更新数据／索引块位图和inode位图。','常规；多层取整与存储位置为综合。',[('位图和空闲结构','位图|位示图|空闲|FAT|释放|inode','按原卷定义0/1含义；FAT可用特殊标记管理空闲，inode记录文件而非通用空闲块表。'),('格式化与设备差异','格式化|块大小|HDD|SSD|扇区','低格建立扇区层组织，逻辑格式化创建文件系统结构；两种设备都要定义文件系统块大小。')])
add('OS16','文件与I/O','目录名、inode、引用','硬链接、软链接及删除名字／关闭文件的区别。','硬链接多个名字指同inode；软链接有自身对象并记录目标路径。删一个硬链接减链接数，目标仍可能存在；删原名可使软链接悬空。','硬链接有独立数据副本；关闭减磁盘链接数；删除目标自动删除所有快捷方式；不同fd必不同inode。','能画名字→inode→数据与打开表关系并逐事件更新计数。','常规；打开引用与硬链接引用混用是主要难点。',[('链接和引用生命周期','.*','最后关闭只影响打开引用／内存结构；底层空间能否释放还取决于链接和仍打开的引用，服从题设简化模型。')])
add('OS17','文件与I/O','磁道距离、服务方向','FCFS/SSTF/SCAN/C-SCAN、移动距离、公平与SSD差异。','先把块号换磁道，再按策略服务；SSTF每次重新比较到当前位置的距离。SCAN方向到端点再反向，C-SCAN单向服务并按题计回绕。','把LOOK与SCAN混用；漏端点和回绕；将同磁道请求排除；旋转延迟算进磁头移动距离。','能列服务序列及每段距离，按题决定终止位置；高分解释磁臂黏着与饥饿区别。','常规；动态到达公平和调度模型边界为综合。',[('调度次序与距离','.*','FCFS保持到达顺序，可避免持续服务同区造成的黏着；不能笼统说SCAN在所有动态场景都无饥饿。SSD无机械寻道，评价依据相应变化。')])
add('OS18','文件与I/O','系统调用、设备接口、中断','I/O分层、逻辑物理命名、驱动职责及输入数据位置。','按用户I/O→设备无关层→驱动→中断处理／控制器组织职责。驱动将设备相关请求转换并控制硬件；输入中断通常先将接口数据取到内核缓冲，后续再复制给用户。','驱动就是纯硬件；块字符设备控制完全相同；中断结束数据必已在用户变量；切态由普通驱动代码完成。','能将每项操作定位软件层和数据位置；高分还原阻塞、输入、中断、唤醒、返回的事件链。','常规到综合；驱动、中断服务和设备无关层的职责边界是重点。',[('分层职责与数据路径','.*','设备独立性通过逻辑名及映射屏蔽差异；驱动对内核提供约定接口，但具体I/O方式可不同。')])
add('OS19','文件与I/O','流水重叠、缓冲独占','单双缓冲时间、预读延迟写、磁盘缓存及SPOOLing。','为设备输入、缓冲复制、CPU处理分别画时间线。单缓冲被复制占用时可能不能接下一块，双缓冲允许交替；首尾阶段单独计算。','直接n乘最长阶段忽略装入排空；缓存只提高单次设备速度；SPOOLing等于内存缓冲。','能解释每个重叠为何允许，给首块至末块处理完成时间；高分区别减少I/O次数与隐藏I/O时间。','综合；缓冲所有权和首尾计时容易出错。',[('缓冲时序与缓存','缓冲|预读|延迟写|滞后写|高速缓存','按题复制与处理是否可重叠推时间式，不无条件套固定公式。'),('假脱机','SPOOLing','外存输入井／输出井配合管理进程将独占设备表现为可共享服务，保留作业排队。')])
add('OS20','文件与I/O','进程地址空间、缓冲和同步','管道与内存映射文件通信。','管道按半双工字节流及有限缓冲判断读空／写满阻塞；内存映射把文件区域映入进程虚拟空间，共享映射可共同访问同一后备数据。','管道自动全双工或无限缓存；mmap返回物理地址；共享数据就自动消除同步需求。','能给出通信对象、地址空间位置和阻塞条件。','基础到常规；选项依半双工和读写端状态判断。',[('管道','管道','保持有限缓冲和读写端语义，是否多个读者写者依题条件，不把逻辑半双工当成只允许两个进程。'),('映射文件','映射','映入各进程虚拟地址空间，物理页可共享，虚拟地址无需相同；读写冲突仍需同步。')])
add('OS21','系统与进程','特权层次、虚拟硬件','VMM、客户OS、多虚拟机和异构ISA模拟的概念辨析。','将VMM与客户OS管理层次分开；一台主机可运行多个虚拟机，客户OS面对虚拟硬件。跨ISA需要解释／翻译等模拟机制，不能等同硬件直接执行。','VMM和客户OS必同特权层；虚拟机不能运行OS；把所有虚拟化等同同ISA硬件加速。','能逐条解释本题四个命题，不扩展到未考的具体虚拟化产品配置。','基础到常规；低频概念也保留边界。',[('VMM和客户系统','.*','“支持不同ISA”应理解为可通过模拟实现，不声称任意硬件虚拟化机制都原生支持跨ISA。')])
